CREATE TABLE users (id text PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE providers (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, name text NOT NULL, type text NOT NULL, base_url text NOT NULL, chat_endpoint text NOT NULL DEFAULT '/chat/completions', models_endpoint text NOT NULL DEFAULT '/models', icon text, is_enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX providers_user_idx ON providers(user_id);
CREATE TABLE api_credentials (provider_id text PRIMARY KEY REFERENCES providers ON DELETE CASCADE, encrypted_api_key text NOT NULL, key_last_four text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_models (id text PRIMARY KEY, provider_id text NOT NULL REFERENCES providers ON DELETE CASCADE, model_id text NOT NULL, display_name text NOT NULL, description text NOT NULL DEFAULT '', context_window integer NOT NULL DEFAULT 32768, max_output_tokens integer NOT NULL DEFAULT 4096, capabilities jsonb NOT NULL DEFAULT '["text"]', supported_options jsonb NOT NULL DEFAULT '["temperature","topP","maxTokens"]', output_token_param text NOT NULL DEFAULT 'max_tokens', reasoning_style text NOT NULL DEFAULT 'none', is_enabled boolean NOT NULL DEFAULT true, is_favorite boolean NOT NULL DEFAULT false, last_used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX model_provider_unique ON ai_models(provider_id, model_id);
CREATE TABLE projects (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX projects_user_idx ON projects(user_id);
CREATE TABLE conversations (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, project_id text REFERENCES projects ON DELETE SET NULL, title text NOT NULL DEFAULT '새 대화', default_model_id text REFERENCES ai_models ON DELETE SET NULL, system_prompt text NOT NULL DEFAULT '', active_leaf_id text, is_pinned boolean NOT NULL DEFAULT false, is_archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX conversations_user_date_idx ON conversations(user_id, updated_at DESC);
CREATE TABLE messages (id text PRIMARY KEY, conversation_id text NOT NULL REFERENCES conversations ON DELETE CASCADE, parent_message_id text, role text NOT NULL CHECK(role IN ('system','user','assistant','tool')), content text NOT NULL DEFAULT '', model_id text REFERENCES ai_models ON DELETE SET NULL, provider_id text REFERENCES providers ON DELETE SET NULL, status text NOT NULL DEFAULT 'complete', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_conversation_idx ON messages(conversation_id);
CREATE INDEX messages_parent_idx ON messages(parent_message_id);
CREATE TABLE attachments (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, conversation_id text REFERENCES conversations ON DELETE CASCADE, message_id text REFERENCES messages ON DELETE CASCADE, project_id text REFERENCES projects ON DELETE CASCADE, name text NOT NULL, mime_type text NOT NULL, size integer NOT NULL, data text NOT NULL, extracted_text text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX attachments_user_idx ON attachments(user_id);
CREATE TABLE user_settings (user_id text PRIMARY KEY REFERENCES users ON DELETE CASCADE, value jsonb NOT NULL);
CREATE TABLE memories (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, content text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shared_conversations (id text PRIMARY KEY, conversation_id text NOT NULL UNIQUE REFERENCES conversations ON DELETE CASCADE, title text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artifacts (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, message_id text NOT NULL REFERENCES messages ON DELETE CASCADE, name text NOT NULL, language text NOT NULL, versions jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text PRIMARY KEY, count integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE INDEX rate_limits_reset_idx ON rate_limits(reset_at);
